Ejecutando JavaScript: `
// Intentar disparar el evento submit del formulario
const form = document.querySelector('form');
if (form) {
  try {
    // Primero intentar con el botón
    const submitButton = document.querySelector('button[type="submit"]') || 
                        Array.from(document.querySelectorAll('button')).find(btn => 
                          btn.textContent.includes('Guardar'));

    if (submitButton) {
      submitButton.click();
      'Button clicked';
    } else {
      'No submit button found';
    }
  } catch (error) {
    'Error: ' + error.message;
  }
} else {
  'No form found';
}
`

